e_xl6_units, IFNULL(jit_xs_units::int, 0)::int AS offline_jit_xs_units, IFNULL(jit_s_units::int, 0)::int AS offline_jit_s_units, IFNULL(jit_m_units::int, 0)::int AS offline_jit_m_units, IFNULL(jit_l_units::int, 0)::int AS offline_jit_l_units, IFNULL(jit_xl_units::int, 0)::int AS offline_jit_xl_units, IFNULL(jit_2xl_units::int, 0)::int AS offline_jit_xxl_units, IFNULL(jit_2xl_units::int, 0)::int AS offline_jit_xl3_units, IFNULL(jit_2xl_units::int, 0)::int AS offline_jit_xl4_units, IFNULL(jit_2xl_units::int, 0)::int AS offline_jit_xl5_units, IFNULL(jit_2xl_units::int, 0)::int AS offline_jit_xl6_units FROM snitch_db.maplemonk.offline_master ), offline_inventory AS ( SELECT *, CASE when left(sku_group,4) = \'4MBG\' and (offline_xl3_units = 0 or offline_xl4_units = 0 or offline_xl5_units = 0) then \'yes\' WHEN offline_s_units = 0 OR offline_m_units = 0 OR offline_l_units = 0 OR offline_xl_units = 0 THEN \'yes\' ELSE \'no\' END AS offline_cut_size_flag FROM offline_inventory_pre ), total_inventory_pre AS ( SELECT COALESCE(a.sku_group::varchar, b.sku_group::varchar) AS sku_group, COALESCE(a.branch_code, b.branch_code) AS branch_code, COALESCE(online_cut_size_flag, \'not_in_channel\') AS online_cut_size_flag, COALESCE(offline_cut_size_flag, \'not_in_channel\') AS offline_cut_size_flag, COALESCE(online_inventory::int, 0)::int AS online_inventory, COALESCE(offline_inventory::int, 0)::int AS offline_inventory, COALESCE(offline_jit_inventory::int, 0)::int AS offline_jit_inventory, COALESCE(online_xs_units::int, 0)::int AS online_xs_units, COALESCE(online_s_units::int, 0)::int AS online_s_units, COALESCE(online_m_units::int, 0)::int AS online_m_units, COALESCE(online_l_units::int, 0)::int AS online_l_units, COALESCE(online_xl_units::int, 0)::int AS online_xl_units, COALESCE(online_xxl_units::int, 0)::int AS online_xxl_units, COALESCE(online_xl3_units::int, 0)::int AS online_xl3_units, COALESCE(online_xl4_units::int, 0)::int AS online_xl4_units, COALESCE(online_xl5_units::int, 0)::int AS online_xl5_units, COALESCE(online_xl6_units::int, 0)::int AS online_xl6_units, COALESCE(offline_xs_units::int, 0)::int AS offline_xs_units, COALESCE(offline_s_units::int, 0)::int AS offline_s_units, COALESCE(offline_m_units::int, 0)::int AS offline_m_units, COALESCE(offline_l_units::int, 0)::int AS offline_l_units, COALESCE(offline_xl_units::int, 0)::int AS offline_xl_units, COALESCE(offline_xxl_units::int, 0)::int AS offline_xxl_units, COALESCE(offline_xl3_units::int, 0)::int AS offline_xl3_units, COALESCE(offline_xl4_units::int, 0)::int AS offline_xl4_units, COALESCE(offline_xl5_units::int, 0)::int AS offline_xl5_units, COALESCE(offline_xl6_units::int, 0)::int AS offline_xl6_units, COALESCE(offline_jit_xs_units::int, 0)::int AS offline_jit_xs_units, COALESCE(offline_jit_s_units::int, 0)::int AS offline_jit_s_units, COALESCE(offline_jit_m_units::int, 0)::int AS offline_jit_m_units, COALESCE(offline_jit_l_units::int, 0)::int AS offline_jit_l_units, COALESCE(offline_jit_xl_units::int, 0)::int AS offline_jit_xl_units, COALESCE(offline_jit_xxl_units::int, 0)::int AS offline_jit_xxl_units, COALESCE(offline_jit_xl3_units::int, 0)::int AS offline_jit_xl3_units, COALESCE(offline_jit_xl4_units::int, 0)::int AS offline_jit_xl4_units, COALESCE(offline_jit_xl5_units::int, 0)::int AS offline_jit_xl5_units, COALESCE(offline_jit_xl6_units::int, 0)::int AS offline_jit_xl6_units FROM online_inventory a FULL OUTER JOIN offline_inventory b ON a.sku_group = b.sku_group AND a.branch_code = b.branch_code ), class AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, MAX(sku_class) AS sku_class FROM snitch_db.maplemonk.availability_master_v2 where sku_class != \'Not-Cataloged\' and status =\'active\' GROUP BY 1 ), total_inventory AS ( SELECT a.*, b.sku_class FROM total_inventory_pre AS a LEFT JOIN class b ON a.sku_group = b.sku_group ), mp_shopify_sales_quant_data AS ( SELECT UPPER(TRIM(sku_group::varchar)) AS sku_group, \'online\' AS branch_code, IFNULL(SUM(CASE WHEN type = \'Marketplace\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_quantity::int END), 0)::int AS mp_quant7, IFNULL(SUM(CASE WHEN type = \'Marketplace\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_quantity::int END), 0)::int AS mp_quant30, IFNULL(SUM(CASE WHEN type = \'Shopify\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_quantity::int END), 0)::int AS shopify_quant7, IFNULL(SUM(CASE WHEN type = \'Shopify\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_quantity::int END), 0)::int AS shopify_quant30, IFNULL(SUM(CASE WHEN type = \'Marketplace\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_sales::int END), 0)::int AS mp_sales30, IFNULL(SUM(CASE WHEN type = \'Marketplace\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_sales::int END), 0)::int AS mp_sales7, IFNULL(SUM(CASE WHEN type = \'Shopify\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_sales::int END), 0)::int AS shopify_sales7, IFNULL(SUM(CASE WHEN type = \'Shopify\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_sales::int END), 0)::int AS shopify_sales30, IFNULL(SUM(CASE WHEN type = \'Shopify\' AND DATEDIFF(day, date, current_date) <= 8 THEN discount_amount::int END), 0)::int AS shopify_discount7, IFNULL(SUM(CASE WHEN type = \'Shopify\' AND DATEDIFF(day, date, current_date) <= 31 THEN discount_amount::int END), 0)::int AS shopify_discount30, IFNULL(SUM(CASE WHEN type = \'Marketplace\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN type = \'Marketplace\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS mp_tax30, IFNULL(SUM(CASE WHEN type = \'Marketplace\' AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN type = \'Marketplace\' AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS mp_tax7, IFNULL(SUM(CASE WHEN type = \'Shopify\' AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN type = \'Shopify\' AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS shopify_tax7, IFNULL(SUM(CASE WHEN type = \'Shopify\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN type = \'Shopify\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS shopify_tax30, IFNULL(SUM(CASE WHEN channel = \'FLIPKART\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_quantity::int END), 0)::int AS flipkart_quant7, IFNULL(SUM(CASE WHEN channel IN (\'NYKAA_FASHION\') AND DATEDIFF(day, date, current_date) <= 8 THEN gross_quantity::int END), 0)::int AS nykaa_quant7, IFNULL(SUM(CASE WHEN LOWER(channel) = \'myntra\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_quantity::int END), 0)::int AS myntra_quant7, IFNULL(SUM(CASE WHEN channel = \'AMAZON\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_quantity::int END), 0)::int AS amazon_quant7, IFNULL(SUM(CASE WHEN channel = \'AJIO\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_quantity::int END), 0)::int AS ajio_quant7, IFNULL(SUM(CASE WHEN channel = \'FLIPKART\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_quantity::int END), 0)::int AS flipkart_quant30, IFNULL(SUM(CASE WHEN channel IN (\'NYKAA_FASHION\') AND DATEDIFF(day, date, current_date) <= 31 THEN gross_quantity::int END), 0)::int AS nykaa_quant30, IFNULL(SUM(CASE WHEN LOWER(channel) = \'myntra\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_quantity::int END), 0)::int AS myntra_quant30, IFNULL(SUM(CASE WHEN channel = \'AMAZON\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_quantity::int END), 0)::int AS amazon_quant30, IFNULL(SUM(CASE WHEN channel = \'AJIO\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_quantity::int END), 0)::int AS ajio_quant30, IFNULL(SUM(CASE WHEN channel = \'FLIPKART\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_sales::int END), 0)::int AS flipkart_sales7, IFNULL(SUM(CASE WHEN channel IN (\'NYKAA_FASHION\') AND DATEDIFF(day, date, current_date) <= 8 THEN gross_sales::int END), 0)::int AS nykaa_sales7, IFNULL(SUM(CASE WHEN LOWER(channel) = \'myntra\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_sales::int END), 0)::int AS myntra_sales7, IFNULL(SUM(CASE WHEN channel = \'AMAZON\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_sales::int END), 0)::int AS amazon_sales7, IFNULL(SUM(CASE WHEN channel = \'AJIO\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_sales::int END), 0)::int AS ajio_sales7, IFNULL(SUM(CASE WHEN channel = \'FLIPKART\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_sales::int END), 0)::int AS flipkart_sales30, IFNULL(SUM(CASE WHEN channel IN (\'NYKAA_FASHION\') AND DATEDIFF(day, date, current_date) <= 31 THEN gross_sales::int END), 0)::int AS nykaa_sales30, IFNULL(SUM(CASE WHEN LOWER(channel) = \'myntra\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_sales::int END), 0)::int AS myntra_sales30, IFNULL(SUM(CASE WHEN channel = \'AMAZON\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_sales::int END), 0)::int AS amazon_sales30, IFNULL(SUM(CASE WHEN channel = \'AJIO\' AND DATEDIFF(day, date, current_date) <= 31 THEN gross_sales::int END), 0)::int AS ajio_sales30, IFNULL(SUM(CASE WHEN channel = \'FLIPKART\' AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN channel = \'FLIPKART\' AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS flipkart_tax7, IFNULL(SUM(CASE WHEN channel IN (\'NYKAA_FASHION\') AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN gross_sales / gross_quantity >= 999 AND channel IN (\'NYKAA_FASHION\') AND DATEDIFF(day, date, current_date) <= 8 THEN gross_sales::int * 0.12 END), 0) AS nykaa_tax7, IFNULL(SUM(CASE WHEN LOWER(channel) = \'myntra\' AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN gross_sales / gross_quantity >= 999 AND LOWER(channel) = \'myntra\' AND DATEDIFF(day, date, current_date) <= 8 THEN gross_sales::int * 0.12 END), 0) AS myntra_tax7, IFNULL(SUM(CASE WHEN channel = \'AMAZON\' AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN channel = \'AMAZON\' AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS amazon_tax7, IFNULL(SUM(CASE WHEN channel = \'AJIO\' AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN channel = \'AJIO\' AND DATEDIFF(day, date, current_date) <= 8 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS ajio_tax7, IFNULL(SUM(CASE WHEN channel = \'FLIPKART\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN channel = \'FLIPKART\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS flipkart_tax30, IFNULL(SUM(CASE WHEN channel IN (\'NYKAA_FASHION\') AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN channel IN (\'NYKAA_FASHION\') AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS nykaa_tax30, IFNULL(SUM(CASE WHEN LOWER(channel) = \'myntra\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN LOWER(channel) = \'myntra\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS myntra_tax30, IFNULL(SUM(CASE WHEN channel = \'AMAZON\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN channel = \'AMAZON\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS amazon_tax30, IFNULL(SUM(CASE WHEN channel = \'AJIO\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity < 999 THEN gross_sales::int * 0.05 WHEN channel = \'AJIO\' AND DATEDIFF(day, date, current_date) <= 31 AND gross_sales / gross_quantity >= 999 THEN gross_sales::int * 0.12 END), 0) AS ajio_tax30 FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1, 2 ), store_sales_quant_data AS ( SELECT UPPER(TRIM(sku_group::varchar)) AS sku_group, branch_code::varchar AS branch_code, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 31 THEN suborder_quantity::int END), 0)::int AS store_quant30, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 8 THEN suborder_quantity::int END), 0)::int AS store_quant7, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 31 THEN selling_price::int END), 0)::int AS store_sales30, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 8 THEN selling_price::int END), 0)::int AS store_sales7, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 31 THEN discount::int END), 0)::int AS store_discount30, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 8 THEN discount::int END), 0)::int AS store_discount7, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 31 AND selling_price / suborder_quantity < 999 THEN selling_price::int * 0.05 WHEN DATEDIFF(day, order_date, current_date) <= 31 AND selling_price / suborder_quantity >= 999 THEN selling_price * 0.12 END), 0) AS store_tax30, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 8 AND selling_price / suborder_quantity < 999 THEN selling_price::int * 0.05 WHEN DATEDIFF(day, order_date, current_date) <= 8 AND selling_price / suborder_quantity >= 999 THEN selling_price::int * 0.12 END), 0) AS store_tax7 FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE LOWER(marketplace_mapped) NOT LIKE \'%wh%\' AND LOWER(sku_group) NOT LIKE \'cb%\' AND suborder_quantity != 0 GROUP BY 1, 2 ), full_price as ( select upper(trim(sku_group)) as sku_group, \'online\' as branch_code, sum(case when datediff(day,order_timestamp::date,current_date) <=8 then quantity::int else 0 end)::int as full_price_shopify_quant7, sum(case when datediff(day,order_timestamp::date,current_date) <=31 then quantity::int else 0 end)::int as full_price_shopify_quant30 from snitch_db.maplemonk.fact_items_snitch WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') and (slashed_discount is null or slashed_discount = 0) group by 1,2 ), slashed_sku AS ( SELECT DISTINCT LEFT(VARIANT.value:sku::STRING, LENGTH(VARIANT.value:sku::STRING) - CHARINDEX(\'-\', REVERSE(VARIANT.value:sku::STRING))) AS sku_group, VARIANT.value:compare_at_price::integer AS cp_price, VARIANT.value:price::integer AS slashed_price, ((cp_price - slashed_price) / cp_price) * 100 AS slashed_discount_percentage FROM snitch_db.maplemonk.shopifyindia_new_products, TABLE(FLATTEN(INPUT => PARSE_JSON(variants))) AS VARIANT WHERE cp_price IS NOT NULL AND cp_price > 0 AND slashed_price < cp_price AND sku_group NOT IN ( \'4MSN1021-03\', \'4MSN1021-01\', \'4MSN1021-White\', \'4MSN1207-WHT-Shirt\', \'4MSN1021-02\', \'4MSN1021-Black\', \'4MSN1021-Navy\') ), metafields_data AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, occassion_new, occassion, print_design, print_design_mapped, collar_mapped, collar, product_tags, material_new, material, rise, pocket, sleeve_type, fit, color, closure, length, vendor, designs, style, mapping, manual_mapping, mapping_final from snitch_db.maplemonk.metafields_data ), category AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, product_name, category FROM snitch_db.maplemonk.availability_master_v2 where sku_class != \'Not-Cataloged\' and status =\'active\' ), product_journey AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, original_price, cost_price, category, inward_count, days_since_inward, days_since_live, DATEADD(day, -days_since_live, current_date) AS live_date, overall_aging, inv_60, inv_90, inv_120, inv_180, inv_240, inv_300, inv_360, strike, marketplace_discount_30_percentage, marketplace_discount_7_percentage, FROM snitch_db.maplemonk.product_journey qualify row_number() over (partition by sku_group order by inventory desc) = 1 ), starting_inventory AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, SUM(inventory) AS starting_inventory, SUM(first_30d_sales) AS first_30d_quant, hit_sizes FROM snitch_db.maplemonk.design_fact_items GROUP BY 1, 4 ), shopify_returns AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, \'online\' AS branch_code, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 8 THEN return_qty END), 0) AS shopify_returns7, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 31 THEN return_qty END), 0) AS shopify_returns30 FROM snitch_db.maplemonk.return_fact_items GROUP BY 1 ), marketplace_returns AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, \'online\' AS branch_code, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 8 THEN return_qty::int END), 0)::int AS marketplace_returns7, IFNULL(SUM(CASE WHEN DATEDIFF(day, order_date, current_date) <= 31 THEN return_qty::int END), 0)::int AS marketplace_returns30, IFNULL(SUM(CASE WHEN LOWER(marketplace) = \'flipkart\' AND DATEDIFF(day, order_date, current_date) <= 8 THEN return_qty::int END), 0)::int AS flipkart_returns7, IFNULL(SUM(CASE WHEN LOWER(marketplace) = \'ajio\' AND DATEDIFF(day, order_date, current_date) <= 8 THEN return_qty::int END), 0)::int AS ajio_returns7, IFNULL(SUM(CASE WHEN LOWER(marketplace) = \'myntra\' AND DATEDIFF(day, order_date, current_date) <= 8 THEN return_qty::int END), 0)::int AS myntra_returns7, IFNULL(SUM(CASE WHEN LOWER(marketplace) = \'amazon\' AND DATEDIFF(day, order_date, current_date) <= 8 THEN return_qty::int END), 0)::int AS amazon_returns7, IFNULL(SUM(CASE WHEN LOWER(marketplace) = \'flipkart\' AND DATEDIFF(day, order_date, current_date) <= 31 THEN return_qty::int END), 0)::int AS flipkart_returns30, IFNULL(SUM(CASE WHEN LOWER(marketplace) = \'ajio\' AND DATEDIFF(day, order_date, current_date) <= 31 THEN return_qty::int END), 0)::int AS ajio_returns30, IFNULL(SUM(CASE WHEN LOWER(marketplace) = \'myntra\' AND DATEDIFF(day, order_date, current_date) <= 31 THEN return_qty::int END), 0)::int AS myntra_returns30, IFNULL(SUM(CASE WHEN LOWER(marketplace) = \'amazon\' AND DATEDIFF(day, order_date, current_date) <= 31 THEN return_qty::int END), 0)::int AS amazon_returns30 FROM snitch_db.maplemonk.marketplace_sales_returns GROUP BY 1 ), sales_inventory_data as ( select coalesce(total_inventory.sku_group,mp_shopify.sku_group,store.sku_group) as sku_group, coalesce(total_inventory.branch_code, mp_shopify.branch_code, store.branch_code) as branch_code, 